class Solution {
  public List<List<Integer>> filterOccupiedIntervals(
      int[][] occupiedIntervals, int freeStart, int freeEnd) {
    int[][] sorted = occupiedIntervals.clone();
    java.util.Arrays.sort(sorted, (a, b) -> Integer.compare(a[0], b[0]));
    List<int[]> merged = new ArrayList<>();
    for (int[] iv : sorted) {
      if (!merged.isEmpty() && iv[0] <= (long) merged.get(merged.size() - 1)[1] + 1) {
        int[] last = merged.get(merged.size() - 1);
        last[1] = Math.max(last[1], iv[1]);
      } else merged.add(new int[] {iv[0], iv[1]});
    }
    List<List<Integer>> res = new ArrayList<>();
    for (int[] iv : merged) {
      if (iv[1] < freeStart || iv[0] > freeEnd) {
        res.add(java.util.Arrays.asList(iv[0], iv[1]));
        continue;
      }
      if (iv[0] < freeStart) res.add(java.util.Arrays.asList(iv[0], freeStart - 1));
      if (iv[1] > freeEnd) res.add(java.util.Arrays.asList(freeEnd + 1, iv[1]));
    }
    return res;
  }
}
